1	<!doctype html>
2	<html lang="en">
3	  <head>
4	    <meta charset="utf-8" />
5	    <meta name="viewport" content="width=device-width, initial-scale=1" />
6	    <title>residual landscape</title>
7	    <style>
8	      :root {
9	        --bg: #12141a;
10	        --surface: #1a1d26;
11	        --ink: #e6e8ee;
12	        --muted: #8b91a0;
13	        --line: #2a3040;
14	        --accent: #3d9b8f;
15	        --coupled: #c4a35a;
16	        --warn: #c45c5c;
17	        --mono: "IBM Plex Mono", "JetBrains Mono", "SF Mono", ui-monospace, monospace;
18	        --sans: "IBM Plex Sans", "Source Sans 3", "Segoe UI", sans-serif;
19	      }
20	      * { box-sizing: border-box; }
21	      body {
22	        margin: 0;
23	        background: radial-gradient(1200px 600px at 10% -10%, #1c2230 0%, var(--bg) 55%);
24	        color: var(--ink);
25	        font: 14px/1.45 var(--sans);
26	      }
27	      header {
28	        padding: 1.25rem 1.5rem 0.75rem;
29	        border-bottom: 1px solid var(--line);
30	      }
31	      header h1 {
32	        margin: 0;
33	        font: 600 1.35rem/1.2 var(--mono);
34	        letter-spacing: 0.04em;
35	        text-transform: lowercase;
36	      }
37	      header p { margin: 0.35rem 0 0; color: var(--muted); max-width: 52rem; }
38	      .view-toolbar {
39	        position: sticky;
40	        top: 0;
41	        z-index: 30;
42	        display: flex;
43	        flex-wrap: wrap;
44	        align-items: center;
45	        gap: 0.75rem;
46	        padding: 0.65rem 1.5rem;
47	        background: color-mix(in srgb, var(--bg) 94%, black);
48	        border-bottom: 1px solid var(--line);
49	      }
50	      .view-toolbar input[data-force-filter] {
51	        flex: 1 1 18rem;
52	        margin: 0;
53	      }
54	      .view-toolbar label {
55	        display: flex;
56	        align-items: center;
57	        gap: 0.4rem;
58	        font: 600 0.72rem/1 var(--mono);
59	        text-transform: uppercase;
60	        letter-spacing: 0.05em;
61	        color: var(--muted);
62	        white-space: nowrap;
63	        margin: 0;
64	      }
65	      .view-toolbar input[type="checkbox"] { width: auto; margin: 0; }
66	      .view-toolbar input[type="range"] { width: 8rem; margin: 0; }
67	      .view-toolbar output {
68	        color: var(--ink);
69	        font: 600 0.75rem var(--mono);
70	        min-width: 1.4rem;
71	        text-align: right;
72	      }
73	      main {
74	        display: flex;
75	        flex-direction: column;
76	        gap: 1.25rem;
77	        padding: 1.25rem 1.5rem 3rem;
78	      }
79	      section {
80	        background: color-mix(in srgb, var(--surface) 92%, black);
81	        border: 1px solid var(--line);
82	        padding: 1rem 1.1rem 1.15rem;
83	        min-width: 0;
84	      }
85	      section[data-view="matrix"] {
86	        /* Break out of main's horizontal padding so calc(100vw - 4em) on
87	           .matrix-scroll below measures from the real viewport edge, not
88	           from inside an already-padded ancestor (which caused page-level
89	           horizontal scroll — the padding chain ate into the 4em budget). */
90	        margin-left: -1.5rem;
91	        margin-right: -1.5rem;
92	        padding: 1rem 2em 1.15rem;
93	        border-left: none;
94	        border-right: none;
95	      }
96	      section h2 {
97	        margin: 0 0 0.75rem;
98	        font: 600 0.78rem/1.2 var(--mono);
99	        letter-spacing: 0.08em;
100	        text-transform: uppercase;
101	        color: var(--muted);
102	      }
103	      input[data-force-filter],
104	      input[type="text"],
105	      textarea,
106	      select {
107	        width: 100%;
108	        background: #0e1016;
109	        color: var(--ink);
110	        border: 1px solid var(--line);
111	        padding: 0.45rem 0.55rem;
112	        font: 13px/1.35 var(--mono);
113	        margin: 0 0 0.55rem;
114	      }
115	      textarea { min-height: 4rem; resize: vertical; }
116	      label {
117	        display: block;
118	        font: 600 0.72rem/1.2 var(--mono);
119	        letter-spacing: 0.06em;
120	        text-transform: uppercase;
121	        color: var(--muted);
122	        margin: 0.35rem 0 0.2rem;
123	      }
124	      .matrix-scroll {
125	        /* section[data-view="matrix"] already breaks out to the viewport
126	           edge with 2em of padding each side, so 100% here *is* the
127	           calc(100vw - 4em) the table should occupy. */
128	        width: 100%;
129	        height: calc(100vh - 5em);
130	        max-width: 100%;
131	        overflow: auto;
132	        border: 1px solid var(--line);
133	      }
134	      table.matrix {
135	        border-collapse: separate;
136	        border-spacing: 0;
137	        font: 12px/1.2 var(--mono);
138	        width: max-content;
139	        min-width: 100%;
140	      }
141	      table.matrix th, table.matrix td {
142	        border-right: 1px solid var(--line);
143	        border-bottom: 1px solid var(--line);
144	        padding: 0.4rem 0.55rem;
145	        text-align: center;
146	        background: var(--surface);
147	        white-space: nowrap;
148	      }
149	      table.matrix thead th {
150	        position: sticky;
151	        top: 0;
152	        z-index: 5;
153	        color: var(--muted);
154	        font-weight: 600;
155	        cursor: pointer;
156	        user-select: none;
157	      }
158	      table.matrix thead th:hover { color: var(--accent); }
159	      table.matrix tfoot th, table.matrix tfoot td {
160	        position: sticky;
161	        bottom: 0;
162	        z-index: 5;
163	        font-weight: 700;
164	        background: color-mix(in srgb, var(--surface) 78%, black);
165	      }
166	      table.matrix tbody th {
167	        text-align: left;
168	        white-space: normal;
169	        max-width: 22rem;
170	        vertical-align: top;
171	      }
172	      table.matrix .sticky-col {
173	        position: sticky;
174	        left: 0;
175	        z-index: 3;
176	        background: color-mix(in srgb, var(--surface) 96%, black);
177	      }
178	      table.matrix .sticky-col-right {
179	        position: sticky;
180	        right: 0;
181	        z-index: 3;
182	        background: color-mix(in srgb, var(--surface) 96%, black);
183	      }
184	      /* Must out-specificity table.matrix .sticky-col(-right) (2 classes)
185	         and table.matrix thead/tfoot th (3 type selectors) — a bare .corner
186	         class loses to both and lets scrolling cells paint over the pinned
187	         corner. */
188	      table.matrix th.corner, table.matrix td.corner { z-index: 9; }
189	      th[data-sort-key].sort-asc::after { content: " \25B2"; }
190	      th[data-sort-key].sort-desc::after { content: " \25BC"; }
191	      .status-dot {
192	        display: inline-block;
193	        width: 0.5rem;
194	        height: 0.5rem;
195	        border-radius: 50%;
196	        margin-right: 0.35rem;
197	      }
198	      .status-dot.status-proposed { background: var(--coupled); }
199	      .status-dot.status-actual { background: var(--accent); }
200	      .status-dot.status-deprecated { background: var(--warn); }
201	      .status-dot.status-other { background: var(--muted); }
202	      .force-accordion-toggle {
203	        background: transparent;
204	        border: none;
205	        color: var(--coupled);
206	        font: 600 13px var(--mono);
207	        cursor: pointer;
208	        padding: 0;
209	      }
210	      .force-detail {
211	        margin-top: 0.4rem;
212	        font: 12px/1.4 var(--sans);
213	        color: var(--muted);
214	      }
215	      .force-detail dl { margin: 0; }
216	      .force-detail dt {
217	        text-transform: uppercase;
218	        letter-spacing: 0.05em;
219	        font-size: 0.65rem;
220	        color: var(--accent);
221	        margin-top: 0.35rem;
222	      }
223	      .force-detail dd { margin: 0; }
224	      table.matrix tbody tr.force-row[hidden] { display: none; }
225	      [data-residue-cell][data-coupled="1"] {
226	        background: color-mix(in srgb, var(--coupled) 28%, transparent);
227	        color: var(--coupled);
228	        font-weight: 700;
229	      }
230	      th[data-fission="1"], td[data-fission="1"] {
231	        outline: 2px solid var(--warn);
232	        outline-offset: -2px;
233	      }
234	      th[data-fusion="1"], td[data-fusion="1"] {
235	        outline: 2px solid var(--coupled);
236	        outline-offset: -2px;
237	      }
238	      .generators {
239	        display: grid;
240	        gap: 0.85rem;
241	      }
242	      @media (min-width: 800px) {
243	        .generators { grid-template-columns: 1fr 1fr; }
244	      }
245	      form[data-command-generator] {
246	        border: 1px solid var(--line);
247	        padding: 0.75rem;
248	        background: #12151d;
249	      }
250	      form[data-command-generator] legend {
251	        font: 600 0.78rem/1 var(--mono);
252	        letter-spacing: 0.06em;
253	        text-transform: uppercase;
254	        color: var(--accent);
255	        padding: 0 0.25rem;
256	      }
257	      button {
258	        background: transparent;
259	        color: var(--ink);
260	        border: 1px solid var(--line);
261	        font: 600 0.75rem/1 var(--mono);
262	        letter-spacing: 0.05em;
263	        text-transform: uppercase;
264	        padding: 0.45rem 0.7rem;
265	        cursor: pointer;
266	      }
267	      button:hover { border-color: var(--accent); color: var(--accent); }
268	      #staged-commands {
269	        width: 100%;
270	        min-height: 8rem;
271	        background: #0a0c10;
272	        color: #cfd6e4;
273	        border: 1px solid var(--line);
274	        font: 12.5px/1.45 var(--mono);
275	        padding: 0.65rem;
276	        white-space: pre;
277	      }
278	      .copy-bar { display: flex; gap: 0.5rem; margin-bottom: 0.5rem; flex-wrap: wrap; }
279	      .defense-records { margin-top: 0.75rem; font: 12.5px/1.4 var(--mono); color: var(--muted); }
280	      .defense-records li { margin: 0.2rem 0; }
281	    </style>
282	  </head>
283	  <body>
284	    <header>
285	      <h1>residual</h1>
286	      <p>Read-only force landscape. Stage <code>residual add …</code> commands here; run them yourself. Nothing on this page mutates the ledger.</p>
287	    </header>
288	    <div class="view-toolbar" data-view-toolbar>
289	      <input
290	        type="search"
291	        data-force-filter
292	        placeholder="filter by id, shortname, kind, attractor, architecture_set…"
293	        aria-label="Filter forces"
294	      />
295	      <label><input type="checkbox" data-fusion-fission-filter /> fusion/fission candidates only</label>
296	      <label>fission threshold
297	        <input type="range" data-threshold-input min="1" max="1" value="1" />
298	        <output data-threshold-value>1</output>
299	      </label>
300	    </div>
301	    <main>
302	      <section data-view="matrix">
303	        <h2>Residue matrix</h2>
304	        <div class="matrix-scroll">{{MATRIX}}</div>
305	      </section>
306	
307	      {{DEFENSE_RECORDS}}
308	
309	      <section>
310	        <h2>Stage adds</h2>
311	        <div class="generators">
312	          <form data-command-generator="stressor">
313	            <fieldset>
314	              <legend>stressor</legend>
315	              <label>description</label>
316	              <input name="description" type="text" required />
317	              <label>attractor-id</label>
318	              <input name="attractor_id" type="text" required />
319	              <label>naive-change</label>
320	              <input name="naive_change" type="text" required />
321	              <label>shortname</label>
322	              <input name="shortname" type="text" />
323	              <label>outcomes</label>
324	              <input name="outcomes" type="text" />
325	              <button type="submit">stage</button>
326	            </fieldset>
327	          </form>
328	          <form data-command-generator="purpose">
329	            <fieldset>
330	              <legend>purpose</legend>
331	              <label>description</label>
332	              <input name="description" type="text" required />
333	              <label>attractor-id</label>
334	              <input name="attractor_id" type="text" required />
335	              <label>naive-change</label>
336	              <input name="naive_change" type="text" required />
337	              <label>shortname</label>
338	              <input name="shortname" type="text" />
339	              <label>outcomes</label>
340	              <input name="outcomes" type="text" />
341	              <button type="submit">stage</button>
342	            </fieldset>
343	          </form>
344	          <form data-command-generator="attractor">
345	            <fieldset>
346	              <legend>attractor</legend>
347	              <label>name</label>
348	              <input name="name" type="text" required />
349	              <label>description</label>
350	              <input name="description" type="text" required />
351	              <label>positive-state</label>
352	              <input name="positive_state" type="text" required />
353	              <label>negative-state</label>
354	              <input name="negative_state" type="text" required />
355	              <button type="submit">stage</button>
356	            </fieldset>
357	          </form>
358	          <form data-command-generator="component">
359	            <fieldset>
360	              <legend>component</legend>
361	              <label>name</label>
362	              <input name="name" type="text" required />
363	              <label>description</label>
364	              <input name="description" type="text" required />
365	              <label>status</label>
366	              <input name="status" type="text" required />
367	              <label>architecture-set</label>
368	              <input name="architecture_set" type="text" required />
369	              <button type="submit">stage</button>
370	            </fieldset>
371	          </form>
372	          {{DEFENSE_FORMS}}
373	        </div>
374	      </section>
375	
376	      <section data-copy-commands>
377	        <h2>Copy commands</h2>
378	        <div class="copy-bar">
379	          <button type="button" id="copy-staged">copy</button>
380	          <button type="button" id="clear-staged">clear</button>
381	        </div>
382	        <textarea id="staged-commands" readonly placeholder="staged residual add … commands appear here"></textarea>
383	      </section>
384	    </main>
385	
386	    <script id="residual-snapshot" type="application/json">{{SNAPSHOT_JSON}}</script>
387	    <script>
388	      function shellQuote(value) {
389	        const s = String(value == null ? "" : value);
390	        if (s.indexOf("\n") !== -1 || s.indexOf("\r") !== -1) {
391	          let escaped = "";
392	          for (const ch of s) {
393	            if (ch === "\\") escaped += "\\\\";
394	            else if (ch === "'") escaped += "\\'";
395	            else if (ch === "\n") escaped += "\\n";
396	            else if (ch === "\r") escaped += "\\r";
397	            else if (ch === "\t") escaped += "\\t";
398	            else escaped += ch;
399	          }
400	          return "$'" + escaped + "'";
401	        }
402	        return "'" + s.replace(/'/g, "'\\''") + "'";
403	      }
404	
405	      function pushFlag(parts, flag, value) {
406	        parts.push(flag + " " + shellQuote(value));
407	      }
408	
409	      function pushOptionalFlag(parts, flag, value) {
410	        if (value != null && String(value) !== "") pushFlag(parts, flag, value);
411	      }
412	
413	      function buildAddCommand(target, fields) {
414	        const f = fields || {};
415	        const parts = ["residual add " + target];
416	        switch (target) {
417	          case "stressor":
418	          case "purpose":
419	          case "meta-purpose":
420	            pushFlag(parts, "--description", f.description || "");
421	            pushFlag(parts, "--attractor-id", f.attractor_id || "");
422	            pushFlag(parts, "--naive-change", f.naive_change || "");
423	            pushOptionalFlag(parts, "--shortname", f.shortname || "");
424	            pushOptionalFlag(parts, "--outcomes", f.outcomes || "");
425	            break;
426	          case "attractor":
427	          case "meta-attractor":
428	            pushFlag(parts, "--name", f.name || "");
429	            pushFlag(parts, "--description", f.description || "");
430	            pushFlag(parts, "--positive-state", f.positive_state || "");
431	            pushFlag(parts, "--negative-state", f.negative_state || "");
432	            break;
433	          case "component":
434	            pushFlag(parts, "--name", f.name || "");
435	            pushFlag(parts, "--description", f.description || "");
436	            pushFlag(parts, "--status", f.status || "");
437	            pushFlag(parts, "--architecture-set", f.architecture_set || "");
438	            break;
439	          case "meta-stressor":
440	            pushFlag(parts, "--description", f.description || "");
441	            pushOptionalFlag(parts, "--shortname", f.shortname || "");
442	            break;
443	          case "defense-persona":
444	          case "defense-strategy":
445	          case "defense-progress":
446	          case "defense-pitch":
447	            pushFlag(parts, "--name", f.name || "");
448	            pushFlag(parts, "--body", f.body || "");
449	            break;
450	          default:
451	            throw new Error("unknown add target: " + target);
452	        }
453	        return parts.join(" ");
454	      }
455	
456	      function formFields(form) {
457	        const data = {};
458	        for (const el of form.querySelectorAll("input, textarea, select")) {
459	          if (!el.name) continue;
460	          data[el.name] = el.value;
461	        }
462	        return data;
463	      }
464	
465	      function appendStaged(command) {
466	        const box = document.getElementById("staged-commands");
467	        box.value = box.value ? box.value + "\n" + command : command;
468	      }
469	
470	      document.querySelectorAll("form[data-command-generator]").forEach((form) => {
471	        form.addEventListener("submit", (ev) => {
472	          ev.preventDefault();
473	          const target = form.getAttribute("data-command-generator");
474	          appendStaged(buildAddCommand(target, formFields(form)));
475	        });
476	      });
477	
478	      const filterInput = document.querySelector("[data-force-filter]");
479	      if (filterInput) {
480	        filterInput.addEventListener("input", () => {
481	          const q = filterInput.value.trim().toLowerCase();
482	          document.querySelectorAll("table.matrix tbody tr.force-row").forEach((row) => {
483	            const hay = (row.getAttribute("data-search") || row.textContent || "").toLowerCase();
484	            row.hidden = q !== "" && hay.indexOf(q) === -1;
485	          });
486	        });
487	      }
488	
489	      document.querySelectorAll("[data-accordion-toggle]").forEach((btn) => {
490	        btn.addEventListener("click", () => {
491	          const detail = btn.nextElementSibling;
492	          if (!detail) return;
493	          const expanded = btn.getAttribute("aria-expanded") === "true";
494	          btn.setAttribute("aria-expanded", String(!expanded));
495	          detail.hidden = expanded;
496	        });
497	      });
498	
499	      function sortMatrixBy(key, dir) {
500	        const table = document.querySelector("table.matrix");
501	        const tbody = table && table.querySelector("tbody");
502	        if (!tbody) return;
503	        const rows = Array.from(tbody.querySelectorAll("tr.force-row"));
504	        const mult = dir === "desc" ? -1 : 1;
505	        rows.sort((ra, rb) => {
506	          if (key === "force") {
507	            const va = ra.getAttribute("data-force-id") || "";
508	            const vb = rb.getAttribute("data-force-id") || "";
509	            return va.localeCompare(vb) * mult;
510	          }
511	          if (key === "total") {
512	            const va = Number(ra.getAttribute("data-row-total") || 0);
513	            const vb = Number(rb.getAttribute("data-row-total") || 0);
514	            return (va - vb) * mult;
515	          }
516	          if (key.indexOf("component:") === 0) {
517	            const comp = key.slice("component:".length);
518	            const ca = ra.querySelector('td[data-component="' + CSS.escape(comp) + '"]');
519	            const cb = rb.querySelector('td[data-component="' + CSS.escape(comp) + '"]');
520	            const va = ca && ca.getAttribute("data-coupled") === "1" ? 1 : 0;
521	            const vb = cb && cb.getAttribute("data-coupled") === "1" ? 1 : 0;
522	            return (va - vb) * mult;
523	          }
524	          return 0;
525	        });
526	        rows.forEach((row) => tbody.appendChild(row));
527	      }
528	
529	      document.querySelectorAll("table.matrix thead th[data-sort-key]").forEach((th) => {
530	        const activate = () => {
531	          const key = th.getAttribute("data-sort-key");
532	          const current = th.classList.contains("sort-asc")
533	            ? "asc"
534	            : th.classList.contains("sort-desc")
535	              ? "desc"
536	              : null;
537	          const next = current === "asc" ? "desc" : "asc";
538	          document.querySelectorAll("table.matrix thead th[data-sort-key]").forEach((other) => {
539	            other.classList.remove("sort-asc", "sort-desc");
540	          });
541	          th.classList.add(next === "asc" ? "sort-asc" : "sort-desc");
542	          sortMatrixBy(key, next);
543	        };
544	        th.addEventListener("click", activate);
545	        th.addEventListener("keydown", (ev) => {
546	          if (ev.key === "Enter" || ev.key === " ") {
547	            ev.preventDefault();
548	            activate();
549	          }
550	        });
551	      });
552	
553	      function computeMatrixCandidates() {
554	        const table = document.querySelector("table.matrix");
555	        const fusion = new Set();
556	        const fission = new Set();
557	        if (!table) return { fusion, fission };
558	
559	        const componentNames = Array.from(table.querySelectorAll("thead th[data-component]")).map((th) =>
560	          th.getAttribute("data-component")
561	        );
562	        const vectors = {};
563	        componentNames.forEach((name) => {
564	          vectors[name] = {};
565	        });
566	        table.querySelectorAll("tbody td[data-residue-cell]").forEach((td) => {
567	          const comp = td.getAttribute("data-component");
568	          const force = td.getAttribute("data-force-id");
569	          if (vectors[comp]) vectors[comp][force] = td.getAttribute("data-coupled") === "1";
570	        });
571	        for (let i = 0; i < componentNames.length; i++) {
572	          for (let j = i + 1; j < componentNames.length; j++) {
573	            const a = vectors[componentNames[i]];
574	            const b = vectors[componentNames[j]];
575	            const forceIds = Object.keys(a);
576	            const identical = forceIds.length > 0 && forceIds.every((fid) => a[fid] === b[fid]);
577	            if (identical) {
578	              fusion.add(componentNames[i]);
579	              fusion.add(componentNames[j]);
580	            }
581	          }
582	        }
583	
584	        const thresholdInput = document.querySelector("[data-threshold-input]");
585	        const threshold = thresholdInput ? Number(thresholdInput.value) : 1;
586	        table.querySelectorAll("tfoot td[data-col-total]").forEach((td) => {
587	          const total = Number(td.getAttribute("data-col-total"));
588	          if (total > threshold) fission.add(td.getAttribute("data-component"));
589	        });
590	
591	        return { fusion, fission };
592	      }
593	
594	      function applyFusionFissionHighlighting() {
595	        const table = document.querySelector("table.matrix");
596	        if (!table) return;
597	        const { fusion, fission } = computeMatrixCandidates();
598	        const componentNames = Array.from(table.querySelectorAll("thead th[data-component]")).map((th) =>
599	          th.getAttribute("data-component")
600	        );
601	        const onlyToggle = document.querySelector("[data-fusion-fission-filter]");
602	        const only = !!(onlyToggle && onlyToggle.checked);
603	
604	        componentNames.forEach((name) => {
605	          const isFusion = fusion.has(name);
606	          const isFission = fission.has(name);
607	          const show = !only || isFusion || isFission;
608	          table.querySelectorAll('[data-component="' + CSS.escape(name) + '"]').forEach((el) => {
609	            el.setAttribute("data-fusion", isFusion ? "1" : "0");
610	            el.setAttribute("data-fission", isFission ? "1" : "0");
611	            el.hidden = !show;
612	          });
613	        });
614	      }
615	
616	      const thresholdInput = document.querySelector("[data-threshold-input]");
617	      const thresholdOutput = document.querySelector("[data-threshold-value]");
618	      const fusionFissionToggle = document.querySelector("[data-fusion-fission-filter]");
619	
620	      function initThreshold() {
621	        if (!thresholdInput) return;
622	        const numForces = document.querySelectorAll("table.matrix tbody tr.force-row").length;
623	        const max = Math.max(1, numForces);
624	        const def = Math.max(1, Math.floor(numForces / 2));
625	        thresholdInput.min = "1";
626	        thresholdInput.max = String(max);
627	        thresholdInput.value = String(def);
628	        if (thresholdOutput) thresholdOutput.textContent = String(def);
629	      }
630	      initThreshold();
631	      applyFusionFissionHighlighting();
632	
633	      if (thresholdInput) {
634	        thresholdInput.addEventListener("input", () => {
635	          if (thresholdOutput) thresholdOutput.textContent = thresholdInput.value;
636	          applyFusionFissionHighlighting();
637	        });
638	      }
639	      if (fusionFissionToggle) {
640	        fusionFissionToggle.addEventListener("change", applyFusionFissionHighlighting);
641	      }
642	
643	      const copyBtn = document.getElementById("copy-staged");
644	      if (copyBtn) {
645	        copyBtn.addEventListener("click", async () => {
646	          const box = document.getElementById("staged-commands");
647	          if (navigator.clipboard && navigator.clipboard.writeText) {
648	            await navigator.clipboard.writeText(box.value);
649	          } else {
650	            box.select();
651	            document.execCommand("copy");
652	          }
653	        });
654	      }
655	      const clearBtn = document.getElementById("clear-staged");
656	      if (clearBtn) {
657	        clearBtn.addEventListener("click", () => {
658	          document.getElementById("staged-commands").value = "";
659	        });
660	      }
661	    </script>
662	  </body>
663	</html>
