11	pub(crate) const TEMPLATE: &str = include_str!("shell.html");
12	
13	/// Token in [`TEMPLATE`] replaced by the serialized snapshot.
14	pub const SNAPSHOT_PLACEHOLDER: &str = "{{SNAPSHOT_JSON}}";
15	
16	/// Element id of the `<script type="application/json">` block holding the snapshot.
17	pub const SNAPSHOT_ELEMENT_ID: &str = "residual-snapshot";
18	
19	const MATRIX_PLACEHOLDER: &str = "{{MATRIX}}";
20	const DEFENSE_FORMS_PLACEHOLDER: &str = "{{DEFENSE_FORMS}}";
21	const DEFENSE_RECORDS_PLACEHOLDER: &str = "{{DEFENSE_RECORDS}}";
22	
23	/// Render the full landscape page for a snapshot.
24	pub fn render_landscape_html(snapshot: &LandscapeSnapshot) -> Result<String> {
25	    let json = escape_script_json(&snapshot.to_json()?);
26	    let matrix = render_matrix(snapshot);
27	    let defense_records = match &snapshot.defense {
28	        Some(defense) => render_defense_records(defense),
29	        None => String::new(),
30	    };
31	    let defense_forms = match &snapshot.defense {
32	        Some(defense) => render_defense_forms(defense),
33	        None => String::new(),
34	    };
35	
36	    let html = TEMPLATE
37	        .replace(SNAPSHOT_PLACEHOLDER, &json)
38	        .replace(MATRIX_PLACEHOLDER, &matrix)
39	        .replace(DEFENSE_RECORDS_PLACEHOLDER, &defense_records)
40	        .replace(DEFENSE_FORMS_PLACEHOLDER, &defense_forms);
41	    Ok(html)
42	}
43	
44	/// Extract the embedded snapshot JSON from rendered HTML (round-trip helper).
45	pub fn extract_snapshot_json(html: &str) -> Option<&str> {
46	    let open = r#"<script id="residual-snapshot" type="application/json">"#;
47	    let start = html.find(open)? + open.len();
48	    let end = html[start..].find("</script>")? + start;
49	    Some(&html[start..end])
50	}
51	
52	/// Prevent ledger text from closing the embedding `<script>` block.
53	fn escape_script_json(json: &str) -> String {
54	    json.replace('<', "\\u003c")
55	}
